'use strict';
const S=WhaleSignals;const prefKey='whale-edge-alert-rules-v2',stateKey='whale-edge-alert-state-v2';let storageOK=true;
function stored(k,fallback){try{const x=JSON.parse(localStorage.getItem(k));return x&&typeof x==='object'?x:fallback;}catch{return fallback}}
function save(k,v){try{localStorage.setItem(k,JSON.stringify(v));return true}catch{storageOK=false;return false}}
let prefs=S.settings(stored(prefKey,{})),alertState=stored(stateKey,{initialized:false,known:[],unread:[],notifications:false});
if(!Array.isArray(alertState.known))alertState.known=[];if(!Array.isArray(alertState.unread))alertState.unread=[];
let directory=[],selectedManager=null;const byID=new Map();
const originalRender=render;render=function(){originalRender();renderFeatures();};
function managerList(){const fetched=new Map((data.managers||[]).map(m=>[String(Number(m.cik)),m]));return directory.length?directory.map(m=>({...m,...fetched.get(String(Number(m.cik)))})):[...fetched.values()];}
function events(){return (data.whale_events||[]).filter(e=>e&&e.id);}
function matching(){return events().filter(e=>S.matches(e,prefs));}
function renderHot(){let rows=data.screen||[];if(el('hot-penny').checked)rows=rows.filter(s=>s.eligible);if(el('hot-unusual').checked)rows=rows.filter(s=>s.relative_volume>=2);rows=S.hot(rows,el('hot-sort').value);el('hot-table').innerHTML=rows.length?table(['Stock','Price','Daily change','Relative volume','Shares traded','Daily $ volume'],rows.slice(0,30).map(s=>[`<a href="${safeURL(s.source)}" target="_blank" rel="noopener">${esc(s.symbol)}</a>`, '$'+num(s.price),ret(s.change),`<span class="${s.relative_volume>=2?'hot-badge':''}">${num(s.relative_volume)}×</span>`,num(s.volume),s.daily_dollar_volume==null?'—':'$'+num(s.daily_dollar_volume)])):empty('No stocks match these activity filters. High-volume status requires at least 2× the prior 20-session average.');const buys=S.buying(events());el('buying-board').innerHTML=buys.length?table(['Stock / issuer','Reported shares bought','Known purchase $','Reporting owners','Reports','Latest filing'],buys.slice(0,20).map(b=>[esc(b.symbol)+'<br><span class="small">'+esc(b.issuer)+'</span>',num(b.shares),'$'+num(b.known_dollars)+(b.missing_prices?' <span class="small">+ unpriced purchases</span>':''),num(b.owners),num(b.reports),esc(b.latest)])):empty('No qualifying recent reported purchases in the loaded sample. This is not evidence of no market buying.');}
function syncRules(){el('share-threshold').value=prefs.shares;el('dollar-threshold').value=prefs.dollars;el('include-changes').checked=prefs.includeChanges;el('followed-only').checked=prefs.followedOnly;}
function eventCard(e,inbox=false){const purchase=e.kind==='disclosed_purchase';const qty=purchase?e.shares:e.shares_added;const read=alertState.unread.includes(e.id);const who=e.manager||e.issuer;const followIDs=e.owner_ciks?.length?e.owner_ciks:[String(Number(e.cik))];const followed=S.isFollowed(e,prefs);return `<article class="alert-item ${inbox&&read?'unread':''}"><div class="row"><span class="${purchase?'tag':'pill'}">${esc(e.label||e.kind)}</span><span class="small">Filed ${esc(e.filed)}</span></div><h3>${esc(who)} · ${esc(e.symbol||e.issuer||e.cusip)}</h3><div class="statsline"><div><strong>${num(qty)}</strong><span class="small">${purchase?'shares purchased':'more shares reported'}</span></div><div><strong>${e.amount==null?'Not disclosed':'$'+num(e.amount)}</strong><span class="small">${purchase?'transaction value':'purchase value unknown'}</span></div></div><p class="small">${purchase?'Transaction date: '+esc(e.transaction_date):'Position period: '+esc(e.period)+' · Compared with '+esc(e.previous_period)}<br>${esc(e.caveat)}</p><div class="row"><a href="${safeURL(e.url)}" target="_blank" rel="noopener">Read original filing ↗</a><button data-event-follow="${esc(e.id)}" class="follow ${followed?'on':''}">${followed?'Following':'Follow reporting owner'}</button></div></article>`;}
function wireEventButtons(){document.querySelectorAll('[data-event-follow]').forEach(b=>b.onclick=()=>{const e=byID.get(b.dataset.eventFollow);if(!e)return;const ids=e.owner_ciks?.length?e.owner_ciks:[String(Number(e.cik))];const is=S.isFollowed(e,prefs);prefs.followed=is?prefs.followed.filter(c=>!ids.includes(c)):[...new Set([...prefs.followed,...ids])];save(prefKey,prefs);renderDirectory();renderEvents();});}
function renderEvents(){const all=matching();byID.clear();events().forEach(e=>byID.set(e.id,e));el('large-events').innerHTML=all.length?`<p class="small">${all.length} matching events · newest filings first · showing up to 100</p>`+all.slice(0,100).map(e=>eventCard(e)).join(''):empty('No disclosed events match these rules. Check source coverage and thresholds; missing feeds do not imply no purchases.');const unread=new Set(alertState.unread);el('alert-count').textContent=all.filter(e=>unread.has(e.id)).length;el('alert-feed').innerHTML=all.length?all.slice(0,100).map(e=>eventCard(e,true)).join(''):empty('No matching alerts yet. Your rules apply to the large-purchase feed and this inbox.');let permission=typeof Notification==='undefined'?'unsupported':Notification.permission;el('notification-status').textContent=`Browser permission: ${permission}. Notifications ${alertState.notifications?'enabled':'off'} on this device. ${storageOK?'':'Storage unavailable: settings last only for this visit.'}`;el('enable-notifications').textContent=alertState.notifications?'Disable browser notifications':'Enable browser notifications';wireEventButtons();}
function renderDirectory(){const q=el('manager-search').value.toLowerCase();const managers=managerList();el('coverage-summary').textContent=`${managers.length} configured institutions · ${prefs.followed.length} followed reporting entities · SEC status: ${data.whale_status||'not checked'}. Follows are saved on this device.`;el('manager-directory').innerHTML=managers.filter(m=>m.name.toLowerCase().includes(q)).map(m=>{const c=String(Number(m.cik));const followed=prefs.followed.includes(c);return `<article class="manager"><div class="eyebrow">INSTITUTION · CIK ${esc(c)}</div><h3 style="margin-top:12px">${esc(m.name)}</h3><div class="small">${esc(m.status||'awaiting first refresh')}<br>Position period: ${esc(m.period)}<br>Filed: ${esc(m.filed)}</div><div class="controls"><button data-follow="${esc(c)}" class="follow ${followed?'on':''}">${followed?'Following':'Follow'}</button><button data-portfolio="${esc(c)}">View portfolio</button></div></article>`}).join('')||empty('No covered managers match your search.');document.querySelectorAll('[data-follow]').forEach(b=>b.onclick=()=>{const c=b.dataset.follow;prefs.followed=prefs.followed.includes(c)?prefs.followed.filter(x=>x!==c):[...prefs.followed,c];save(prefKey,prefs);renderDirectory();renderEvents();});document.querySelectorAll('[data-portfolio]').forEach(b=>b.onclick=()=>{selectedManager=b.dataset.portfolio;renderPortfolio();el('portfolio-panel').scrollIntoView({behavior:'smooth',block:'start'});});if(selectedManager)renderPortfolio();}
function renderPortfolio(){const m=managerList().find(m=>String(Number(m.cik))===selectedManager);if(!m)return;const panel=el('portfolio-panel');panel.classList.remove('hidden');const changes=new Map((m.changes||[]).map(e=>[e.cusip+'|'+e.security,e]));panel.innerHTML=`<div class="notice"><strong>${esc(m.name)}</strong><br>${esc(m.note||'No verified portfolio data loaded yet.')}<br>Period ${esc(m.period)} · Filed ${esc(m.filed)} · ${num(m.holdings_count)} eligible reported positions</div>`+(m.holdings?.length?table(['Issuer','Security','CUSIP','Reported shares','Quarterly increase'],m.holdings.map(h=>{let c=changes.get(h.cusip+'|'+h.security);return [esc(h.issuer),esc(h.security),esc(h.cusip),num(h.shares),c?'+'+num(c.shares_added):'—'];})):empty('Holdings are unavailable. Source health explains any retrieval errors.'))+(m.url?`<p><a href="${safeURL(m.url)}" target="_blank" rel="noopener">View SEC report ↗</a></p>`:'');}
function processNewEvents(){const all=events();if(!all.length)return;const fresh=S.newNotifications(all,alertState.known,alertState.initialized,prefs);alertState.unread=[...new Set([...alertState.unread,...fresh.map(e=>e.id)])].slice(-5000);alertState.known=[...new Set([...alertState.known,...all.map(e=>e.id)])].slice(-10000);const wasInitialized=alertState.initialized;alertState.initialized=true;save(stateKey,alertState);if(fresh.length&&wasInitialized){let t=document.createElement('div');t.className='toast';t.setAttribute('role','status');t.textContent=`${fresh.length} new matching disclosure${fresh.length===1?'':'s'}. Open Alerts to review.`;document.body.appendChild(t);setTimeout(()=>t.remove(),8000);if(alertState.notifications&&typeof Notification!=='undefined'&&Notification.permission==='granted'){try{new Notification('Whale Edge: new disclosures',{body:`${fresh.length} matching disclosure${fresh.length===1?'':'s'}. Review filing dates and source details in Alerts.`,tag:'whale-edge-new'});}catch{el('notification-status').textContent='Desktop delivery unavailable in this browser; in-app alerts remain active.'}}}}
function renderFeatures(){processNewEvents();renderHot();renderDirectory();renderEvents();const coverage=data.purchase_coverage;const h=el('health');if(coverage)h.insertAdjacentHTML('beforeend',`<p>Purchase feed: ${esc(coverage.status)} · ${num(coverage.parsed_filings)} filings parsed<br>${esc(coverage.description)}<br>Last SEC attempt: ${esc(data.whale_checked_at)}</p>`);}
el('save-thresholds').onclick=()=>{const a=Number(el('share-threshold').value),b=Number(el('dollar-threshold').value);if(!Number.isFinite(a)||!Number.isFinite(b)||a<0||b<0){el('rule-status').textContent='Enter nonnegative numeric thresholds.';return;}prefs=S.settings({...prefs,shares:a,dollars:b,includeChanges:el('include-changes').checked,followedOnly:el('followed-only').checked});const ok=save(prefKey,prefs);el('rule-status').textContent=ok?'Rules saved on this device. Changes apply to the feed and future alerts.':'Rules applied for this visit; browser storage is unavailable.';renderEvents();};
el('hot-sort').onchange=renderHot;el('hot-penny').onchange=renderHot;el('hot-unusual').onchange=renderHot;el('manager-search').oninput=renderDirectory;
el('follow-all').onclick=()=>{prefs.followed=[...new Set([...prefs.followed,...managerList().map(m=>String(Number(m.cik)))])];save(prefKey,prefs);renderDirectory();renderEvents();};el('unfollow-all').onclick=()=>{prefs.followed=[];save(prefKey,prefs);renderDirectory();renderEvents();};
el('read-alerts').onclick=()=>{alertState.unread=[];save(stateKey,alertState);renderEvents();};
el('enable-notifications').onclick=async()=>{if(alertState.notifications){alertState.notifications=false;save(stateKey,alertState);renderEvents();return;}if(typeof Notification==='undefined'){el('notification-status').textContent='This browser does not support desktop notifications. The in-app inbox still works.';return;}try{const permission=await Notification.requestPermission();alertState.notifications=permission==='granted';save(stateKey,alertState);renderEvents();}catch{el('notification-status').textContent='Permission could not be requested. In-app alerts remain available.'}};
el('export-events').onclick=()=>download('whale-edge-disclosures.csv',matching().map(e=>({type:e.kind,reporting_owner:e.manager,stock:e.symbol||e.issuer,shares:e.kind==='disclosed_purchase'?e.shares:e.shares_added,purchase_dollars:e.amount,transaction_date:e.transaction_date||'',period:e.period||'',filed:e.filed,source:e.url})));
syncRules();fetch('managers.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(x=>{directory=x;renderDirectory()}).catch(()=>renderDirectory());renderFeatures();
